using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using UnityEngine;

public class TcpBleSimulator : IBlePlugin
{
    public bool IsConnected { get; private set; }

    public event Action<byte[]> OnDataReceived;
    public event Action<bool> OnConnectionChanged;
    public event Action<string> OnError;

    private TcpListener _listener;
    private TcpClient _client;
    private NetworkStream _stream;
    private Thread _listenThread;
    private volatile bool _running;
    private readonly int _port;
    private readonly byte _expectedPacketSize = 39;

    public TcpBleSimulator(int port = 9877)
    {
        _port = port;
    }

    public void Begin()
    {
        _running = true;
        _listenThread = new Thread(ListenLoop) { IsBackground = true };
        _listenThread.Start();
        Debug.Log($"[TcpBleSimulator] 监听端口 {_port}，等待手表模拟器连接...");
    }

    public void Stop()
    {
        _running = false;
        CloseClient();
        if (_listener != null)
        {
            try { _listener.Stop(); } catch { }
            _listener = null;
        }
        if (_listenThread != null && _listenThread.IsAlive)
        {
            _listenThread.Join(2000);
        }
        SetConnected(false);
    }

    private void ListenLoop()
    {
        try
        {
            _listener = new TcpListener(IPAddress.Any, _port);
            _listener.Start();

            while (_running)
            {
                if (!_listener.Pending())
                {
                    Thread.Sleep(100);
                    continue;
                }

                _client = _listener.AcceptTcpClient();
                _stream = _client.GetStream();
                SetConnected(true);
                Debug.Log("[TcpBleSimulator] 模拟器已连接");

                byte[] buffer = new byte[_expectedPacketSize];
                while (_running && _client.Connected)
                {
                    int offset = 0;
                    while (offset < _expectedPacketSize)
                    {
                        int read = _stream.Read(buffer, offset, _expectedPacketSize - offset);
                        if (read == 0) break;
                        offset += read;
                    }

                    if (offset == _expectedPacketSize)
                    {
                        byte[] packet = new byte[_expectedPacketSize];
                        Array.Copy(buffer, packet, _expectedPacketSize);
                        OnDataReceived?.Invoke(packet);
                    }
                }

                CloseClient();
                SetConnected(false);
                Debug.Log("[TcpBleSimulator] 模拟器已断开");
            }
        }
        catch (Exception ex)
        {
            if (_running) OnError?.Invoke($"TcpBleSimulator: {ex.Message}");
        }
    }

    private void CloseClient()
    {
        if (_stream != null) { try { _stream.Close(); } catch { } _stream = null; }
        if (_client != null) { try { _client.Close(); } catch { } _client = null; }
    }

    private void SetConnected(bool connected)
    {
        if (IsConnected != connected)
        {
            IsConnected = connected;
            OnConnectionChanged?.Invoke(connected);
        }
    }
}
using UnityEngine;
using System.Collections.Generic;

public class NoteTrack : MonoBehaviour
{
    [Header("音符设置")]
    public GameObject notePrefab;
    public Transform noteContainer;
    public float scrollSpeed = 400f;
    public float judgmentLineY = 300f;
    public float spawnOffset = 600f;
    public float despawnBelow = -100f;

    [Header("音符样式")]
    public Color noteColor = new Color(0.1f, 0.3f, 0.7f, 1f);

    private List<NoteVisual> _notes = new List<NoteVisual>();
    private float _songStartTime;

    public struct NoteVisual
    {
        public GameObject obj;
        public RectTransform rect;
        public float targetTime;
        public bool judged;
    }

    public void SetupTrack(List<float> noteTimesSeconds, float songStartTime)
    {
        ClearTrack();
        _songStartTime = songStartTime;

        foreach (float t in noteTimesSeconds)
        {
            GameObject noteObj = Instantiate(notePrefab, noteContainer);
            noteObj.SetActive(false);

            var img = noteObj.GetComponent<UnityEngine.UI.Image>();
            if (img != null) img.color = noteColor;

            _notes.Add(new NoteVisual
            {
                obj = noteObj,
                rect = noteObj.GetComponent<RectTransform>(),
                targetTime = t,
                judged = false
            });
        }
    }

    public void UpdateTrack(float currentSongTime)
    {
        float lookAhead = spawnOffset / scrollSpeed;

        foreach (var note in _notes)
        {
            if (note.judged) continue;

            float timeUntilHit = note.targetTime - currentSongTime;

            if (timeUntilHit > lookAhead)
            {
                note.obj.SetActive(false);
                continue;
            }

            if (!note.obj.activeSelf) note.obj.SetActive(true);

            float yPos = judgmentLineY - timeUntilHit * scrollSpeed;
            note.rect.anchoredPosition = new Vector2(0, yPos);

            if (yPos < despawnBelow)
            {
                note.obj.SetActive(false);
            }
        }
    }

    public void MarkNearestNoteJudged(float currentSongTime, float windowSeconds)
    {
        float bestDist = float.MaxValue;
        int bestIdx = -1;

        for (int i = 0; i < _notes.Count; i++)
        {
            if (_notes[i].judged) continue;
            float dist = Mathf.Abs(_notes[i].targetTime - currentSongTime);
            if (dist < bestDist && dist <= windowSeconds)
            {
                bestDist = dist;
                bestIdx = i;
            }
        }

        if (bestIdx >= 0)
        {
            var n = _notes[bestIdx];
            n.judged = true;
            _notes[bestIdx] = n;
        }
    }

    public void ClearTrack()
    {
        foreach (var note in _notes)
        {
            if (note.obj != null) Destroy(note.obj);
        }
        _notes.Clear();
    }

    void OnDestroy()
    {
        ClearTrack();
    }
}
